(222283, 12879, 5628, '<td valign="top">Very nice! One of my favourites this week!</td>', 'Very nice! One of my favourites this week!', '2003-02-24 07:43:08.000000', NULL, 1),
(222288, 12902, 6458, '<td valign="top">This picture is great - evocative and emotional. The blue tint screams "depression, despair", the title  and the barely lit cross provide the contextual cues. It makes my heart ache to think about it.</td>', 'This picture is great - evocative and emotional. The blue tint screams "depression, despair", the title  and the barely lit cross provide the contextual cues. It makes my heart ache to think about it.', '2003-02-24 07:48:41.000000', NULL, 1),
