(222315, 12910, 5364, '<td valign="top">This would have worked for me, if it hadn''t been for the date-time stamp.</td>', 'This would have worked for me, if it hadn''t been for the date-time stamp.', '2003-02-24 08:37:49.000000', NULL, 1),
(222316, 12886, 5728, '<td valign="top">This photo just cries out "despair" and you have captured it well. It''s a pity you cropped out his toe in this shot, it''s the only point which bothers me here. I hope you gave him a few coins afterwards :-) 9 from me.</td>', 'This photo just cries out "despair" and you have captured it well. It''s a pity you cropped out his toe in this shot, it''s the only point which bothers me here. I hope you gave him a few coins afterwards :-) 9 from me.', '2003-02-24 08:39:12.000000', NULL, 1),
