(222846, 13007, 4159, '<td valign="top">Looks like she''s hiking, not contemplating suicide.  I''m not sure your angle is effective.</td>', 'Looks like she''s hiking, not contemplating suicide.  I''m not sure your angle is effective.', '2003-02-24 14:43:33.000000', NULL, 1),
(222848, 12775, 4055, '<td valign="top">This is my absolute favourite this week. Focus, lighting and composition are all very good. Perfect in b&amp;w. Well done. High score from Sweden.</td>', 'This is my absolute favourite this week. Focus, lighting and composition are all very good. Perfect in b&w. Well done. High score from Sweden.', '2003-02-24 14:44:59.000000', NULL, 1),
(222849, 13124, 4159, '<td valign="top">Interesting abstract, I suppose...I have no idea why you chose a bright pink border, it''s mildly painful.  Can''t say this evokes the feeling of despair.</td>', 'Interesting abstract, I suppose...I have no idea why you chose a bright pink border, it''s mildly painful.  Can''t say this evokes the feeling of despair.', '2003-02-24 14:45:07.000000', NULL, 1),
(222850, 13026, 4159, '<td valign="top">Just looks too staged to evoke the feeling of despair, for me.</td>', 'Just looks too staged to evoke the feeling of despair, for me.', '2003-02-24 14:45:36.000000', NULL, 1),
(222851, 13065, 4159, '<td valign="top">Grainy.</td>', 'Grainy.', '2003-02-24 14:45:58.000000', NULL, 1),
(222852, 12861, 4159, '<td valign="top">This statue is supposed to represent hope, not despair.  Too bright in places, glare in bottom right.</td>', 'This statue is supposed to represent hope, not despair.  Too bright in places, glare in bottom right.', '2003-02-24 14:46:25.000000', NULL, 1),
(222853, 13107, 6405, '<td valign="top">your lens was little dirty here,I see no despair here!</td>', 'your lens was little dirty here,I see no despair here!', '2003-02-24 14:47:17.000000', NULL, 1),
(222854, 12856, 6405, '<td valign="top">Light hits the pear in the face, try to avoid that</td>', 'Light hits the pear in the face, try to avoid that', '2003-02-24 14:48:21.000000', NULL, 1),
(222855, 12933, 4055, '<td valign="top">Great composition. One of my favourites this week. Focus and lighting are veru good. And this kind if sepia tone is perfect. Well done and high score is coming.</td>', 'Great composition. One of my favourites this week. Focus and lighting are veru good. And this kind if sepia tone is perfect. Well done and high score is coming.', '2003-02-24 14:48:28.000000', NULL, 1),
(222856, 13107, 4159, '<td valign="top">Dosn''t seem to be holding on so much as sticking out.  Nice try at symbolism, though; most of the pictures are more literal in their interpretation.</td>', 'Dosn''t seem to be holding on so much as sticking out.  Nice try at symbolism, though; most of the pictures are more literal in their interpretation.', '2003-02-24 14:48:36.000000', NULL, 1),
(222857, 12951, 4159, '<td valign="top">Stark, which is effective.</td>', 'Stark, which is effective.', '2003-02-24 14:49:17.000000', NULL, 1),
(222858, 12973, 6405, '<td valign="top">nnice pic but being a Muslim woman is not a despair</td>', 'nnice pic but being a Muslim woman is not a despair', '2003-02-24 14:49:23.000000', NULL, 1),
(222859, 12910, 3260, '<td valign="top">need to remove that timestamp from the corner.</td>', 'need to remove that timestamp from the corner.', '2003-02-24 14:49:51.000000', NULL, 1),
(222861, 13034, 4159, '<td valign="top">Interesting use of color, truly a disturbing picture.  This is post-despair, though, and more unsettling than evocative of that emotion.</td>', 'Interesting use of color, truly a disturbing picture.  This is post-despair, though, and more unsettling than evocative of that emotion.', '2003-02-24 14:50:17.000000', NULL, 1),
(222863, 13080, 6405, '<td valign="top">I like the photo quality, but I don''t see any despair here</td>', 'I like the photo quality, but I don''t see any despair here', '2003-02-24 14:50:45.000000', NULL, 1),
(222864, 12918, 4159, '<td valign="top">Very blurry, and too obviously staged.  Background is cluttered and distracting.</td>', 'Very blurry, and too obviously staged.  Background is cluttered and distracting.', '2003-02-24 14:50:54.000000', NULL, 1),
(222865, 12950, 4055, '<td valign="top">Simple and lovely. One of my favourites this week. Nice colours and focus is good. Your composition is perfect. Well done and good luck!</td>', 'Simple and lovely. One of my favourites this week. Nice colours and focus is good. Your composition is perfect. Well done and good luck!', '2003-02-24 14:51:08.000000', NULL, 1),
(222866, 12871, 4159, '<td valign="top">Nice expression here, but the background is distracting and the cat is out of focus.</td>', 'Nice expression here, but the background is distracting and the cat is out of focus.', '2003-02-24 14:51:14.000000', NULL, 1),
(222868, 12873, 4159, '<td valign="top">This would have worked in the rhythm challenge.  I like the gradient of colors.  I can''t say it really fits despairing, though - death is a good deal more final than emotion, and a pretty different realm altogether.  Nice picture, though.</td>', 'This would have worked in the rhythm challenge.  I like the gradient of colors.  I can''t say it really fits despairing, though - death is a good deal more final than emotion, and a pretty different realm altogether.  Nice picture, though.', '2003-02-24 14:52:32.000000', NULL, 1),
(222869, 12834, 4159, '<td valign="top">This is hope, not despair.</td>', 'This is hope, not despair.', '2003-02-24 14:52:43.000000', NULL, 1),
