(222939, 12887, 6791, '<td valign="top">That is despair.</td>', 'That is despair.', '2003-02-24 15:25:15.000000', NULL, 1),
(222940, 12916, 6025, '<td valign="top">Writing a suicide note with a sharpie? God, man, at least have the decency to use a fountain pen or something else classy. :P Sorry, couldn''t help myself. Good image, but it doesn''t really show a sense of urgency and despair. The writing is calm and the grip of the pen is firm and calm.. Not a bad shot, though. (6)</td>', 'Writing a suicide note with a sharpie? God, man, at least have the decency to use a fountain pen or something else classy. :P Sorry, couldn''t help myself. Good image, but it doesn''t really show a sense of urgency and despair. The writing is calm and the grip of the pen is firm and calm.. Not a bad shot, though. (6)', '2003-02-24 15:25:17.000000', NULL, 1),
(222942, 12871, 5266, '<td valign="top">Poor funnel kitty!! Hope the funnel''s off!!  Soft in focus or you would have gotten a better mark!!!</td>', 'Poor funnel kitty!! Hope the funnel''s off!!  Soft in focus or you would have gotten a better mark!!!', '2003-02-24 15:26:35.000000', NULL, 1),
(222943, 12814, 6791, '<td valign="top">YES! Awinning photo! EXCELLENT!</td>', 'YES! Awinning photo! EXCELLENT!', '2003-02-24 15:27:08.000000', NULL, 1),
(222944, 12826, 6791, '<td valign="top">GOOD!</td>', 'GOOD!', '2003-02-24 15:27:39.000000', NULL, 1),
(222947, 12996, 6458, '<td valign="top">Wonderful shot! The noise really gives a strong  emotional impression to me, and the starkness of the water against the black of the hand creates a lasting image in my mind. The only thing that bothers me is the arm visible underneath the water. It ruins the impression of the "last grasp" before the subject sinks beneath the waves... still 9 for a striking image.</td>', 'Wonderful shot! The noise really gives a strong  emotional impression to me, and the starkness of the water against the black of the hand creates a lasting image in my mind. The only thing that bothers me is the arm visible underneath the water. It ruins the impression of the "last grasp" before the subject sinks beneath the waves... still 9 for a striking image.', '2003-02-24 15:32:09.000000', NULL, 1),
(222948, 12871, 5899, '<td valign="top">Too blurry for my taste, and I don''t like the background</td>', 'Too blurry for my taste, and I don''t like the background', '2003-02-24 15:33:49.000000', NULL, 1),
(222950, 12930, 6458, '<td valign="top">Noise, blue, and subject make this memorable - good job.</td>', 'Noise, blue, and subject make this memorable - good job.', '2003-02-24 15:34:44.000000', NULL, 1),
(222951, 13026, 6791, '<td valign="top">Good,simple creativityis very nice!</td>', 'Good,simple creativityis very nice!', '2003-02-24 15:35:11.000000', NULL, 1),
