(223005, 12893, 6597, '<td valign="top">there''s been better days certainly meets challenge</td>', 'there''s been better days certainly meets challenge', '2003-02-24 16:04:31.000000', NULL, 1),
(223008, 13034, 3102, '<td valign="top">I would certainly hope this was staged... but man... I''ll have to give you extra points for sticking her hair in the toilet!  Dang, there''s no way on Earth I''d do that!  And even if it happened accidentally after an alcohol-fueled night, I''d shave my head!  Anyway, I really think this is a strong shot.  Way to go.</td>', 'I would certainly hope this was staged... but man... I''ll have to give you extra points for sticking her hair in the toilet!  Dang, there''s no way on Earth I''d do that!  And even if it happened accidentally after an alcohol-fueled night, I''d shave my head!  Anyway, I really think this is a strong shot.  Way to go.', '2003-02-24 16:05:17.000000', NULL, 1),
(223010, 13029, 6597, '<td valign="top">this surely meets the challenge</td>', 'this surely meets the challenge', '2003-02-24 16:05:32.000000', NULL, 1),
