(223014, 12973, 6597, '<td valign="top">can''t connect with despair</td>', 'can''t connect with despair', '2003-02-24 16:07:32.000000', NULL, 1),
(223015, 13019, 3102, '<td valign="top">Unfortunately this seems to be of a very low image quality.  The file size is only 12K, compared to the 150K allowable on the site.  You might want to learn to use the maximum-allowed quality for future submissions -- it''ll definitely help ya out :)</td>', 'Unfortunately this seems to be of a very low image quality.  The file size is only 12K, compared to the 150K allowable on the site.  You might want to learn to use the maximum-allowed quality for future submissions -- it''ll definitely help ya out :)', '2003-02-24 16:09:16.000000', NULL, 1),
(223016, 12770, 3102, '<td valign="top">I have to admit it took me a few looks to figure out what I was looking at!  That must have been quite a nasty storm!</td>', 'I have to admit it took me a few looks to figure out what I was looking at!  That must have been quite a nasty storm!', '2003-02-24 16:13:11.000000', NULL, 1),
(223017, 12776, 3102, '<td valign="top">Awesome subject -- one of the best of this challenge!  Seems like the colors could have been just a teeny bit more bold, but still a 9 in my book.</td>', 'Awesome subject -- one of the best of this challenge!  Seems like the colors could have been just a teeny bit more bold, but still a 9 in my book.', '2003-02-24 16:14:17.000000', NULL, 1),
(223018, 12949, 2223, '<td valign="top">I can''t make heads or tails of this..</td>', 'I can''t make heads or tails of this..', '2003-02-24 16:14:44.000000', NULL, 1),
(223019, 12941, 3102, '<td valign="top">Awesome expression!  I hope you gave him something he wanted after this :)</td>', 'Awesome expression!  I hope you gave him something he wanted after this :)', '2003-02-24 16:15:11.000000', NULL, 1),
(223020, 12856, 2223, '<td valign="top">LOL!</td>', 'LOL!', '2003-02-24 16:15:39.000000', NULL, 1),
(223021, 12962, 3102, '<td valign="top">Great work!  You certainly captured a powerful expression here.  I may have liked it a little tighter, to capture his face a little closer up... but still an awesome shot.<br/><br/><i>Message edited by author 2003-03-03 16:22:02.</i></td>', 'Great work!  You certainly captured a powerful expression here.  I may have liked it a little tighter, to capture his face a little closer up... but still an awesome shot.', '2003-02-24 16:16:32.000000', '2003-03-03 16:22:02.000000', 1),
(223022, 12908, 5391, '<td valign="top">Excellent framing and composition and saturated colors that keep the eye interested.  So far after perusing these images, I''ve noticed that a lot of people have taken the challenge description and used it to not pay attention to basic, good photography principles.  You took a photo of an ugly situation, brought feeling across, and made it interesting to the eye with composition and lighting.  Nice work.  9</td>', 'Excellent framing and composition and saturated colors that keep the eye interested.  So far after perusing these images, I''ve noticed that a lot of people have taken the challenge description and used it to not pay attention to basic, good photography principles.  You took a photo of an ugly situation, brought feeling across, and made it interesting to the eye with composition and lighting.  Nice work.  9', '2003-02-24 16:16:47.000000', NULL, 1),
(223023, 13017, 5899, '<td valign="top">Almost reminds me of some parts of my own city...</td>', 'Almost reminds me of some parts of my own city...', '2003-02-24 16:17:11.000000', NULL, 1),
(223024, 13083, 3102, '<td valign="top">Certainly does a great job of capturing the mood of dispair!  Seems like the contrast may be just a little exaggerated, but otherwise it''s just great.</td>', 'Certainly does a great job of capturing the mood of dispair!  Seems like the contrast may be just a little exaggerated, but otherwise it''s just great.', '2003-02-24 16:17:36.000000', NULL, 1),
(223025, 13106, 3102, '<td valign="top">I''m afraid I just don''t get this one... sorry...  It looks like letters made of cigarettes, which only serves to confuse me more.</td>', 'I''m afraid I just don''t get this one... sorry...  It looks like letters made of cigarettes, which only serves to confuse me more.', '2003-02-24 16:20:08.000000', NULL, 1),
(223027, 12771, 5899, '<td valign="top">Wow, _very_ low JPEG quality, and it''s hard to make out what it really is, but not altogether bad</td>', 'Wow, _very_ low JPEG quality, and it''s hard to make out what it really is, but not altogether bad', '2003-02-24 16:22:11.000000', NULL, 1),
(223030, 12966, 5899, '<td valign="top">I don''t get it. Why so small?</td>', 'I don''t get it. Why so small?', '2003-02-24 16:25:15.000000', NULL, 1),
(223031, 12865, 6870, '<td valign="top">Nice composition. Love the lines. I think it does say "despair."</td>', 'Nice composition. Love the lines. I think it does say "despair."', '2003-02-24 16:26:09.000000', NULL, 1),
(223032, 13011, 6870, '<td valign="top">Very nice set up. Soft lighting works for me. Great composition.</td>', 'Very nice set up. Soft lighting works for me. Great composition.', '2003-02-24 16:27:08.000000', NULL, 1),
(223033, 12870, 6870, '<td valign="top">A very  nice photo with a lot of interest. Tones and lines are wonderful. The dark shadows work for me. I''m not sure it says "despair", other than the title, and it could use a little sharpening.</td>', 'A very  nice photo with a lot of interest. Tones and lines are wonderful. The dark shadows work for me. I''m not sure it says "despair", other than the title, and it could use a little sharpening.', '2003-02-24 16:29:00.000000', NULL, 1),
(223034, 13083, 6870, '<td valign="top">I like the high contrast and grainy journalistic feel to this; it seems very appropriate. George looks like he''s acting. I suspect that this is a friend dressed for the occasion? The composition is also nice with the fence at down right.</td>', 'I like the high contrast and grainy journalistic feel to this; it seems very appropriate. George looks like he''s acting. I suspect that this is a friend dressed for the occasion? The composition is also nice with the fence at down right.', '2003-02-24 16:31:17.000000', NULL, 1),
(223036, 12795, 6870, '<td valign="top">Good stuff. rhythms and patterns are very nice. Very subdued grays here. Have you tried adding more contrast to give lighter lights and darker darks? I''m not sure if that would improve the  image, but may well be worth trying.</td>', 'Good stuff. rhythms and patterns are very nice. Very subdued grays here. Have you tried adding more contrast to give lighter lights and darker darks? I''m not sure if that would improve the  image, but may well be worth trying.', '2003-02-24 16:33:09.000000', NULL, 1),
(223037, 12852, 6870, '<td valign="top">A very journalistic shot, in my view. Very busy, but the focus is clearly on the roof. the white at left adds some neutral space, which relieves the eye. For me, it says "snow collapsed roof" more than it does "despair."</td>', 'A very journalistic shot, in my view. Very busy, but the focus is clearly on the roof. the white at left adds some neutral space, which relieves the eye. For me, it says "snow collapsed roof" more than it does "despair."', '2003-02-24 16:34:52.000000', NULL, 1),
(223038, 12814, 6870, '<td valign="top">You caught some great colors here! The composition is fantastic, too. The placement of the surfer in the upper left third is perfect and makes us focus on the problem: the waves and ocean. rather than despair, it looks fun! But maybe that''s because I was once a surfer (when I lived in So. Calif.)!</td>', 'You caught some great colors here! The composition is fantastic, too. The placement of the surfer in the upper left third is perfect and makes us focus on the problem: the waves and ocean. rather than despair, it looks fun! But maybe that''s because I was once a surfer (when I lived in So. Calif.)!', '2003-02-24 16:36:49.000000', NULL, 1),
(223041, 12992, 6870, '<td valign="top">Gritty, gutsy, meaningful photo that haunts me (as it should). In this photo, you might try fiddling with contrasts as well to get darker darks. The composition is good, too with the victim at lower left. A very nice candid!</td>', 'Gritty, gutsy, meaningful photo that haunts me (as it should). In this photo, you might try fiddling with contrasts as well to get darker darks. The composition is good, too with the victim at lower left. A very nice candid!', '2003-02-24 16:38:27.000000', NULL, 1),
(223044, 12897, 4159, '<td valign="top">Looks more bored than dispairing.  Is this posed?  I''ve never seen anyone actually put their arm on their hand like that.</td>', 'Looks more bored than dispairing.  Is this posed?  I''ve never seen anyone actually put their arm on their hand like that.', '2003-02-24 16:39:10.000000', NULL, 1),
(223048, 12827, 6870, '<td valign="top">Despair for the mammal, triumph for the eagle. Since the eagle clearly  has focus here, the shot doesn''t speak despair to me, but would be great for a hunter-themed challenge. If you had the ability, you might''ve tried shifting so that the mammal was more central. I love the fence: good eye!</td>', 'Despair for the mammal, triumph for the eagle. Since the eagle clearly  has focus here, the shot doesn''t speak despair to me, but would be great for a hunter-themed challenge. If you had the ability, you might''ve tried shifting so that the mammal was more central. I love the fence: good eye!', '2003-02-24 16:41:18.000000', NULL, 1),
(223049, 13121, 4159, '<td valign="top">I can see malice, hate, or desperation at the end of this, but not despair.  Effective photographic presentation, though.</td>', 'I can see malice, hate, or desperation at the end of this, but not despair.  Effective photographic presentation, though.', '2003-02-24 16:41:23.000000', NULL, 1),
(223050, 13012, 4159, '<td valign="top">Funny, sort of. More depressing, and makes light of a not-so-light subject.</td>', 'Funny, sort of. More depressing, and makes light of a not-so-light subject.', '2003-02-24 16:42:06.000000', NULL, 1),
(223051, 12881, 6870, '<td valign="top">Deceptive photo (delightfully). Just looks like some cliche shot of a tombstone until you see the objects placed around it. I wish they were more in focus or that they somehow had more attention. Nice observation.</td>', 'Deceptive photo (delightfully). Just looks like some cliche shot of a tombstone until you see the objects placed around it. I wish they were more in focus or that they somehow had more attention. Nice observation.', '2003-02-24 16:42:52.000000', NULL, 1),
(223052, 13039, 4159, '<td valign="top">Would have been perfect for the leading line challenge, but I don''t see despair in it.  I see sad memory, but there is more of a desperation to despair than a memorial can evoke.</td>', 'Would have been perfect for the leading line challenge, but I don''t see despair in it.  I see sad memory, but there is more of a desperation to despair than a memorial can evoke.', '2003-02-24 16:43:03.000000', NULL, 1),
(223053, 12826, 4159, '<td valign="top">Is this really despair?  Looks like bad luck and disappointment to me.</td>', 'Is this really despair?  Looks like bad luck and disappointment to me.', '2003-02-24 16:43:41.000000', NULL, 1),
(223055, 12844, 6870, '<td valign="top">Putting the lion high in the photo helps with your drought theme expressed in the title, putting him higher might have even been more helpful in this regard so we could really focus on the dry ground.</td>', 'Putting the lion high in the photo helps with your drought theme expressed in the title, putting him higher might have even been more helpful in this regard so we could really focus on the dry ground.', '2003-02-24 16:44:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(223056, 12884, 4159, '<td valign="top">Where''s the despair?  Someone''s dead, sure, but their tombstone doesn''t communicate despair.  Just kind of a sad story.  Effective presentation of the tombstone, nonetheless.</td>', 'Where''s the despair?  Someone''s dead, sure, but their tombstone doesn''t communicate despair.  Just kind of a sad story.  Effective presentation of the tombstone, nonetheless.', '2003-02-24 16:44:44.000000', NULL, 1),
(223057, 13111, 6870, '<td valign="top">Nice shot. The clouds add interest to an appropriately dull sky, and I like the bold lines of the chimneys.</td>', 'Nice shot. The clouds add interest to an appropriately dull sky, and I like the bold lines of the chimneys.', '2003-02-24 16:45:18.000000', NULL, 1),
(223058, 12844, 4159, '<td valign="top">Nice capture.  Doesn''t meet the challenge except by some pretty creative acrobatics of imagination.</td>', 'Nice capture.  Doesn''t meet the challenge except by some pretty creative acrobatics of imagination.', '2003-02-24 16:45:33.000000', NULL, 1),
