(223314, 12936, 4159, '<td valign="top">Ah, yes.  If only architecture could emote.</td>', 'Ah, yes.  If only architecture could emote.', '2003-02-24 19:28:01.000000', NULL, 1),
(223315, 12828, 6505, '<td valign="top">More like boredom. I like the smoke effect with the light.</td>', 'More like boredom. I like the smoke effect with the light.', '2003-02-24 19:28:09.000000', NULL, 1),
(223317, 12919, 6870, '<td valign="top">Spooky.</td>', 'Spooky.', '2003-02-24 19:28:30.000000', NULL, 1),
(223318, 12826, 2223, '<td valign="top">I know the feeling.</td>', 'I know the feeling.', '2003-02-24 19:28:39.000000', NULL, 1),
(223319, 12846, 4159, '<td valign="top">Nice dismal colors and forlorn-looking tree.</td>', 'Nice dismal colors and forlorn-looking tree.', '2003-02-24 19:28:43.000000', NULL, 1),
(223321, 12996, 6870, '<td valign="top">Good placement and use of sillhouette.</td>', 'Good placement and use of sillhouette.', '2003-02-24 19:29:49.000000', NULL, 1),
(223324, 12798, 6870, '<td valign="top">Best wilted flower shot so far! Use of color and focus is subtle and magnificent.</td>', 'Best wilted flower shot so far! Use of color and focus is subtle and magnificent.', '2003-02-24 19:30:46.000000', NULL, 1),
(223325, 12941, 6870, '<td valign="top">Good portrait. I really enjoy the tones and contrasts here.</td>', 'Good portrait. I really enjoy the tones and contrasts here.', '2003-02-24 19:31:18.000000', NULL, 1),
(223327, 12815, 6870, '<td valign="top">Empty hangers are a nice touch!</td>', 'Empty hangers are a nice touch!', '2003-02-24 19:31:41.000000', NULL, 1),
(223329, 12829, 6870, '<td valign="top">Nice tonal values set off both boat and mast.</td>', 'Nice tonal values set off both boat and mast.', '2003-02-24 19:33:07.000000', NULL, 1),
(223331, 13040, 2716, '<td valign="top">Wow!  Very powerfull image.  i love the colours.  The elements really work well together.  Jacko.  10</td>', 'Wow!  Very powerfull image.  i love the colours.  The elements really work well together.  Jacko.  10', '2003-02-24 19:34:10.000000', NULL, 1),
(223332, 13026, 6870, '<td valign="top">I love the light on the dollar bill.</td>', 'I love the light on the dollar bill.', '2003-02-24 19:35:21.000000', NULL, 1),
(223334, 13027, 3072, '<td valign="top">Your photo should be in black and white, the guy should not wear a watch and he should be more relaxed, less tense, relaxed in the acceptance of total defeat.</td>', 'Your photo should be in black and white, the guy should not wear a watch and he should be more relaxed, less tense, relaxed in the acceptance of total defeat.', '2003-02-24 19:36:18.000000', NULL, 1),
(223335, 12911, 6870, '<td valign="top">to me, this image suggests a life that will be full of suffering. Works.</td>', 'to me, this image suggests a life that will be full of suffering. Works.', '2003-02-24 19:36:41.000000', NULL, 1),
(223336, 12956, 6870, '<td valign="top">Candid expression is great. My eye is led from the face to the cookie. Good use of triangles to focus on cookie.</td>', 'Candid expression is great. My eye is led from the face to the cookie. Good use of triangles to focus on cookie.', '2003-02-24 19:37:30.000000', NULL, 1),
(223339, 12873, 6870, '<td valign="top">A very grave scene. Tones suggest despair.</td>', 'A very grave scene. Tones suggest despair.', '2003-02-24 19:38:16.000000', NULL, 1),
(223341, 12886, 6505, '<td valign="top">That''s heartbreaking and real.  It''s a shame that this happens.  This photo is real and tragic.</td>', 'That''s heartbreaking and real.  It''s a shame that this happens.  This photo is real and tragic.', '2003-02-24 19:39:00.000000', NULL, 1),
(223342, 13040, 6870, '<td valign="top">Stylized image that works well for me. Does it violate the layers rules? I hope it does well.</td>', 'Stylized image that works well for me. Does it violate the layers rules? I hope it does well.', '2003-02-24 19:39:19.000000', NULL, 1),
(223343, 12992, 2716, '<td valign="top">ah geee ... I''d really to see this in full size.  Good eye.  Jacko.  8</td>', 'ah geee ... I''d really to see this in full size.  Good eye.  Jacko.  8', '2003-02-24 19:39:55.000000', NULL, 1),
(223345, 12901, 6870, '<td valign="top">Title works well with the image. Nice background. The best chess image I''ve seen.</td>', 'Title works well with the image. Nice background. The best chess image I''ve seen.', '2003-02-24 19:40:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(223347, 12886, 2716, '<td valign="top">Very powerful image.  Goo capture.  The sepia tone adds to the feeling of despair.  Good luck.  Jacko.  10</td>', 'Very powerful image.  Goo capture.  The sepia tone adds to the feeling of despair.  Good luck.  Jacko.  10', '2003-02-24 19:40:59.000000', NULL, 1),
(223348, 13026, 5088, '<td valign="top">Cute idea. The lighting''s a little dark, though.</td>', 'Cute idea. The lighting''s a little dark, though.', '2003-02-24 19:41:29.000000', NULL, 1),
(223349, 13046, 6870, '<td valign="top">Good cropping and good acting. I hope it''s acting...</td>', 'Good cropping and good acting. I hope it''s acting...', '2003-02-24 19:41:48.000000', NULL, 1),
(223350, 12891, 6520, '<td valign="top">Great shot, great subject! Thank God the rower made it to shore. That boat would be under 5 feet of snow where I am! Kudos, Gets an 8</td>', 'Great shot, great subject! Thank God the rower made it to shore. That boat would be under 5 feet of snow where I am! Kudos, Gets an 8', '2003-02-24 19:42:25.000000', NULL, 1),
(223351, 13016, 6870, '<td valign="top">INteresting image that invites the eye to wander while still having focus.</td>', 'INteresting image that invites the eye to wander while still having focus.', '2003-02-24 19:42:30.000000', NULL, 1),
(223354, 12949, 6870, '<td valign="top">I like the contrasty, journalistic feel of this image. The dark trees really make this image work.</td>', 'I like the contrasty, journalistic feel of this image. The dark trees really make this image work.', '2003-02-24 19:43:17.000000', NULL, 1),
(223355, 13029, 6870, '<td valign="top">I like the image, and grain is a good idea, though I find that this looks like you added grain rather than let grain appear?if that makes any sense.</td>', 'I like the image, and grain is a good idea, though I find that this looks like you added grain rather than let grain appear?if that makes any sense.', '2003-02-24 19:44:31.000000', NULL, 1),
(223357, 12939, 6870, '<td valign="top">. . . or triumphant? Nice light and contrasts.</td>', '. . . or triumphant? Nice light and contrasts.', '2003-02-24 19:45:49.000000', NULL, 1),
(223359, 12892, 5088, '<td valign="top">Haha! Very funny picture. :P</td>', 'Haha! Very funny picture. :P', '2003-02-24 19:46:03.000000', NULL, 1),
(223362, 12989, 6870, '<td valign="top">The eye is led up the stairs. Good guidance. Cool textures.</td>', 'The eye is led up the stairs. Good guidance. Cool textures.', '2003-02-24 19:46:33.000000', NULL, 1),
(223364, 12986, 6870, '<td valign="top">A sulking elephant. I like this image. The placement of the eye is great. Try experimenting with contrasts.</td>', 'A sulking elephant. I like this image. The placement of the eye is great. Try experimenting with contrasts.', '2003-02-24 19:47:37.000000', NULL, 1),
(223368, 13037, 6870, '<td valign="top">Nice sports shot. Captures the essence and despair of wrestling!</td>', 'Nice sports shot. Captures the essence and despair of wrestling!', '2003-02-24 19:49:54.000000', NULL, 1),
(223369, 12856, 5088, '<td valign="top">Very cute and clever idea! :)</td>', 'Very cute and clever idea! :)', '2003-02-24 19:50:40.000000', NULL, 1),
(223370, 12911, 6505, '<td valign="top">I think this is an excellent photo although it doesn''t communicate despair to me.  It does communicate many other things.  Great job.  I wish i didn''t have to mark it lower for the topic.</td>', 'I think this is an excellent photo although it doesn''t communicate despair to me.  It does communicate many other things.  Great job.  I wish i didn''t have to mark it lower for the topic.', '2003-02-24 19:51:07.000000', NULL, 1),
(223371, 12811, 6870, '<td valign="top">Wonderful tones!</td>', 'Wonderful tones!', '2003-02-24 19:51:29.000000', NULL, 1),
(223374, 13028, 6870, '<td valign="top">I can see the idea here, but the flowers are still the triumphant ones.</td>', 'I can see the idea here, but the flowers are still the triumphant ones.', '2003-02-24 19:54:24.000000', NULL, 1),
(223375, 13044, 6870, '<td valign="top">Clever. Lighting, especially on roll, is good.</td>', 'Clever. Lighting, especially on roll, is good.', '2003-02-24 19:55:01.000000', NULL, 1),
(223381, 12833, 5088, '<td valign="top">Haha! Very funny idea! :)</td>', 'Haha! Very funny idea! :)', '2003-02-24 20:01:23.000000', NULL, 1),
(223387, 13014, 4267, '<td valign="top">lol, ok you made me laugh.. as for the shot, I might have tried darken the color channel of the background so it looked washed out and the texture and wrinkles could not be seen... might take doing in layers, but I think this technique works well in hiding the source of the background...</td>', 'lol, ok you made me laugh.. as for the shot, I might have tried darken the color channel of the background so it looked washed out and the texture and wrinkles could not be seen... might take doing in layers, but I think this technique works well in hiding the source of the background...', '2003-02-24 20:03:29.000000', NULL, 1),
(223388, 12947, 4267, '<td valign="top">go for black and white here... then adjust the brightness and contrast to washout the background so it looks like negative space... would help a lot here</td>', 'go for black and white here... then adjust the brightness and contrast to washout the background so it looks like negative space... would help a lot here', '2003-02-24 20:04:13.000000', NULL, 1),
(223390, 12851, 6520, '<td valign="top">I like it! Gets an 7</td>', 'I like it! Gets an 7', '2003-02-24 20:06:28.000000', NULL, 1),
(223392, 12790, 6505, '<td valign="top">Really cool place and shot.  No sense of despair for me, though.  Sorry.</td>', 'Really cool place and shot.  No sense of despair for me, though.  Sorry.', '2003-02-24 20:08:44.000000', NULL, 1),
(223401, 13126, 4159, '<td valign="top">Upping the contrast and using a mroe agressive crop would have made this a very effective picture.</td>', 'Upping the contrast and using a mroe agressive crop would have made this a very effective picture.', '2003-02-24 20:14:46.000000', NULL, 1),
(223402, 13077, 4159, '<td valign="top">Overall, the exposure is too much, and the depiction of "despair" is a bit weak, IMO.  I do like your composition.</td>', 'Overall, the exposure is too much, and the depiction of "despair" is a bit weak, IMO.  I do like your composition.', '2003-02-24 20:15:51.000000', NULL, 1),
(223404, 13044, 4159, '<td valign="top">Interesting if lighthearted take on the challenge.  It''s certainly a feeling most of us can relate to.</td>', 'Interesting if lighthearted take on the challenge.  It''s certainly a feeling most of us can relate to.', '2003-02-24 20:16:23.000000', NULL, 1),
(223405, 12949, 6520, '<td valign="top">Not sharp enough</td>', 'Not sharp enough', '2003-02-24 20:16:48.000000', NULL, 1),
(223409, 12892, 4159, '<td valign="top">I really like this photo on its own, although I think it may not quite achieve what the challenge''s parameters intended.  It would make a very funny spot in the Onion, though.</td>', 'I really like this photo on its own, although I think it may not quite achieve what the challenge''s parameters intended.  It would make a very funny spot in the Onion, though.', '2003-02-24 20:17:57.000000', NULL, 1),
(223411, 12852, 4159, '<td valign="top">Looks like the roof was already collapsed, else the snow would have fallen off when it did...maybe not, doesn''t matter.  Too cluttered for an effective presentation, for me.</td>', 'Looks like the roof was already collapsed, else the snow would have fallen off when it did...maybe not, doesn''t matter.  Too cluttered for an effective presentation, for me.', '2003-02-24 20:18:48.000000', NULL, 1),
(223413, 12911, 4159, '<td valign="top">I like the texture, and the grain may help the effect.  Seems to be carved in stone.</td>', 'I like the texture, and the grain may help the effect.  Seems to be carved in stone.', '2003-02-24 20:19:58.000000', NULL, 1),
(223416, 12950, 4159, '<td valign="top">One of the first realistic stagings of despair I''ve seen so far.  This is well presented and composed, esp. with use of neg. space.</td>', 'One of the first realistic stagings of despair I''ve seen so far.  This is well presented and composed, esp. with use of neg. space.', '2003-02-24 20:21:58.000000', NULL, 1),
(223422, 12887, 6223, '<td valign="top">One of my favorites!! Good job...sad enough!</td>', 'One of my favorites!! Good job...sad enough!', '2003-02-24 20:25:57.000000', NULL, 1),
(223426, 12995, 6008, '<td valign="top">The colors, or lack thereof, are a good choice for the subject. I do not really like the narrow crop, but that is more of a personal preference. I believe the challenge was met.</td>', 'The colors, or lack thereof, are a good choice for the subject. I do not really like the narrow crop, but that is more of a personal preference. I believe the challenge was met.', '2003-02-24 20:28:35.000000', NULL, 1),
(223440, 12775, 4564, '<td valign="top">Superb image.  To me the shot speaks more of desolation than despair.  Never the less, since it''s only a question of interpretation, and your shot being so good, I''m giving it a 9.  Great use of B/W by the way.</td>', 'Superb image.  To me the shot speaks more of desolation than despair.  Never the less, since it''s only a question of interpretation, and your shot being so good, I''m giving it a 9.  Great use of B/W by the way.', '2003-02-24 20:36:22.000000', NULL, 1),
(223441, 12838, 6008, '<td valign="top">It''s an interesting shot, I like the texture of the bark on the tree. I think I can see the face (or what looks similar), but I dont really see any despair.</td>', 'It''s an interesting shot, I like the texture of the bark on the tree. I think I can see the face (or what looks similar), but I dont really see any despair.', '2003-02-24 20:36:37.000000', NULL, 1),
(223444, 12874, 4564, '<td valign="top">Fascinating image. Great use of color.  I wish you hadn''t put the red outline.  I think it''s destracting of the image itself and it didn''t need the extra dramatic effect I feel you tried to achieve with the red outline.  I wonder how you shot this one and look forward to your comments after the challenge.  8/10</td>', 'Fascinating image. Great use of color.  I wish you hadn''t put the red outline.  I think it''s destracting of the image itself and it didn''t need the extra dramatic effect I feel you tried to achieve with the red outline.  I wonder how you shot this one and look forward to your comments after the challenge.  8/10', '2003-02-24 20:37:51.000000', NULL, 1),
(223446, 13079, 6008, '<td valign="top">The crop is tight but good. The comparison with old and new is a nice addition. I can also understand the despair that the image is showing.</td>', 'The crop is tight but good. The comparison with old and new is a nice addition. I can also understand the despair that the image is showing.', '2003-02-24 20:38:48.000000', NULL, 1),
(223447, 12778, 6597, '<td valign="top">very good</td>', 'very good', '2003-02-24 20:38:55.000000', NULL, 1),
(223449, 12959, 4564, '<td valign="top">Really nice image. Lighting and color are very good. Framing is really nice too.  The blur is a littlebit distracting.  Without the title, it doesn''t speak much of despair though... Because of that, I feel it didn''t meet up with the challenge.  I''m lowering my score a bit.  6/10</td>', 'Really nice image. Lighting and color are very good. Framing is really nice too.  The blur is a littlebit distracting.  Without the title, it doesn''t speak much of despair though... Because of that, I feel it didn''t meet up with the challenge.  I''m lowering my score a bit.  6/10', '2003-02-24 20:39:34.000000', NULL, 1),
(223451, 12891, 6597, '<td valign="top">looks like trouble to me</td>', 'looks like trouble to me', '2003-02-24 20:39:53.000000', NULL, 1),
(223455, 12884, 6597, '<td valign="top">fits the challenge</td>', 'fits the challenge', '2003-02-24 20:41:53.000000', NULL, 1),
(223458, 12782, 4388, '<td valign="top">nice image but doesn''t say "no hope" to me</td>', 'nice image but doesn''t say "no hope" to me', '2003-02-24 20:42:24.000000', NULL, 1),
(223459, 12770, 4564, '<td valign="top">Many snow images in this challenge. None as great as yours.  Excellent composition, exposure, lighting.  Great use of the negative black space.  Fantastic detail in the snow.  The car looks great too! (just kidding) 9/10</td>', 'Many snow images in this challenge. None as great as yours.  Excellent composition, exposure, lighting.  Great use of the negative black space.  Fantastic detail in the snow.  The car looks great too! (just kidding) 9/10', '2003-02-24 20:42:27.000000', NULL, 1),
(223461, 12949, 4564, '<td valign="top">Excellent composition. Great use of sepia.  Great angle.  9/10</td>', 'Excellent composition. Great use of sepia.  Great angle.  9/10', '2003-02-24 20:45:21.000000', NULL, 1),
(223464, 13017, 4564, '<td valign="top">Very well done. Great colors.  Subject is well framed.  Missing a little wow factor, but very good nonetheless. 8/10</td>', 'Very well done. Great colors.  Subject is well framed.  Missing a little wow factor, but very good nonetheless. 8/10', '2003-02-24 20:46:16.000000', NULL, 1),
(223467, 12900, 4388, '<td valign="top">where is the "no hope"</td>', 'where is the "no hope"', '2003-02-24 20:47:47.000000', NULL, 1),
(223468, 12811, 4564, '<td valign="top">nice composition. excellent subject.  Nice use of natural lighting.  good framing and angle.  I question the use of that particular color but it wont affect the rating I give.  8/10</td>', 'nice composition. excellent subject.  Nice use of natural lighting.  good framing and angle.  I question the use of that particular color but it wont affect the rating I give.  8/10', '2003-02-24 20:48:25.000000', NULL, 1),
(223473, 13124, 6458, '<td valign="top">Ohhhhh.. finally! Got it! The pink border doesn''t help the photo, but at least I understand now.</td>', 'Ohhhhh.. finally! Got it! The pink border doesn''t help the photo, but at least I understand now.', '2003-02-24 20:49:51.000000', NULL, 1),
(223475, 13020, 4564, '<td valign="top">I don''t understand your title... I think you mean it to be funny (is the needle cheating on her husband with the wire?).  Never the less, I think it''s an excellent photo. I don''t know about despair, other maybe with the fact that it''s so damn tough to get the wire through the needle. :-)  Nice colors!  8/10</td>', 'I don''t understand your title... I think you mean it to be funny (is the needle cheating on her husband with the wire?).  Never the less, I think it''s an excellent photo. I don''t know about despair, other maybe with the fact that it''s so damn tough to get the wire through the needle. :-)  Nice colors!  8/10', '2003-02-24 20:51:04.000000', NULL, 1),
(223477, 12879, 6855, '<td valign="top">I think this is an absolutely GORGEOUS photograph! One of my FAVORITES.  The only thing I would change...moving the light to his clasped hands instead of his feet, since the hands really set the mood for the picture.  Still a high score and an awesome photo. Great job!</td>', 'I think this is an absolutely GORGEOUS photograph! One of my FAVORITES.  The only thing I would change...moving the light to his clasped hands instead of his feet, since the hands really set the mood for the picture.  Still a high score and an awesome photo. Great job!', '2003-02-24 20:51:35.000000', NULL, 1),
(223478, 12789, 4388, '<td valign="top">Jesus gives us hope, not despair.</td>', 'Jesus gives us hope, not despair.', '2003-02-24 20:51:51.000000', NULL, 1),
(223479, 12893, 6008, '<td valign="top">The image is a little dark in places and the rose could do with a lot more light/sharpness. A plain background would have helped also - whatever is in the top left hand corner is very distracting.</td>', 'The image is a little dark in places and the rose could do with a lot more light/sharpness. A plain background would have helped also - whatever is in the top left hand corner is very distracting.', '2003-02-24 20:52:02.000000', NULL, 1),
(223480, 13040, 4564, '<td valign="top">People will ask to disqualify your photo  I''m sure.    I personally think it''s excellent!  Right on par with the theme.  Very dramatic.  Excellent framing.  9/10</td>', 'People will ask to disqualify your photo  I''m sure.    I personally think it''s excellent!  Right on par with the theme.  Very dramatic.  Excellent framing.  9/10', '2003-02-24 20:52:05.000000', NULL, 1),
(223481, 12795, 6458, '<td valign="top">This brings back memories of my childhood and of finding an old car out back of our property. I wish there were a bit less clutter and a bit more contrast, but it''s still a good image!</td>', 'This brings back memories of my childhood and of finding an old car out back of our property. I wish there were a bit less clutter and a bit more contrast, but it''s still a good image!', '2003-02-24 20:52:10.000000', NULL, 1),
(223482, 13072, 4564, '<td valign="top">I don''t see the relation with despair.  Extremely well shot though.  5/10 because it really doesn''t mean the challenge to me.  Otherwise, 8/10 for the photo.</td>', 'I don''t see the relation with despair.  Extremely well shot though.  5/10 because it really doesn''t mean the challenge to me.  Otherwise, 8/10 for the photo.', '2003-02-24 20:52:55.000000', NULL, 1),
(223487, 12995, 6855, '<td valign="top">As much as I like the idea of this photo, it looks just a bit too posed.  She is obviously a clean-cut, well loved little girl!  I would recommend messying her hair a bit and giving her a dirty face and hands.  The blanket is also a bit too polished.  I still love it though and gave it a good score!  Great job.</td>', 'As much as I like the idea of this photo, it looks just a bit too posed.  She is obviously a clean-cut, well loved little girl!  I would recommend messying her hair a bit and giving her a dirty face and hands.  The blanket is also a bit too polished.  I still love it though and gave it a good score!  Great job.', '2003-02-24 20:54:21.000000', NULL, 1),
(223488, 12911, 4388, '<td valign="top">this could have been a great image if it wasn''t so grainy, try NeatImage. Also it doesn''t meet the challenge, despair is no hope.</td>', 'this could have been a great image if it wasn''t so grainy, try NeatImage. Also it doesn''t meet the challenge, despair is no hope.', '2003-02-24 20:54:22.000000', NULL, 1),
(223489, 12891, 4564, '<td valign="top">Some despair.. maybe...  very well shot though. 7/10</td>', 'Some despair.. maybe...  very well shot though. 7/10', '2003-02-24 20:54:35.000000', NULL, 1),
(223492, 12974, 4564, '<td valign="top">I love the dramatic angle of your shot. Congrats.  Nice colors. Nice framing. 8/10</td>', 'I love the dramatic angle of your shot. Congrats.  Nice colors. Nice framing. 8/10', '2003-02-24 20:55:01.000000', NULL, 1),
(223493, 13039, 4388, '<td valign="top">despair to me is no hope, this wall gives me hope.</td>', 'despair to me is no hope, this wall gives me hope.', '2003-02-24 20:55:26.000000', NULL, 1),
(223494, 13058, 4564, '<td valign="top">7/10 for originality and for capturing these two great expressions!  Nice framing.</td>', '7/10 for originality and for capturing these two great expressions!  Nice framing.', '2003-02-24 20:56:13.000000', NULL, 1),
(223495, 13095, 6008, '<td valign="top">I remember being a child with a similar problem and thinking it was the end of the world - an interesting take on the despair theme. The composition is good, lighting is good, and it''s expressive.</td>', 'I remember being a child with a similar problem and thinking it was the end of the world - an interesting take on the despair theme. The composition is good, lighting is good, and it''s expressive.', '2003-02-24 20:56:20.000000', NULL, 1),
(223498, 12805, 4564, '<td valign="top">NIce framing. Nice use of B&amp;W.  On par with the theme to some extent.  7/10</td>', 'NIce framing. Nice use of B&W.  On par with the theme to some extent.  7/10', '2003-02-24 20:57:20.000000', NULL, 1),
(223500, 13111, 4564, '<td valign="top">Nicelly framed. Good use of B&amp;W.  Very good photo.  Too bad the image is so compressed and we see the compression artifacts...  7/10</td>', 'Nicelly framed. Good use of B&W.  Very good photo.  Too bad the image is so compressed and we see the compression artifacts...  7/10', '2003-02-24 20:57:29.000000', NULL, 1),
(223501, 12807, 6855, '<td valign="top">Very sad photo - please tell me those aren''t real bruises!  My only "complaint" about this photo is how candid it looks - like what they would take at a hospital of a battered woman.  Still heart-wrenching and definitely meets the challenge!!</td>', 'Very sad photo - please tell me those aren''t real bruises!  My only "complaint" about this photo is how candid it looks - like what they would take at a hospital of a battered woman.  Still heart-wrenching and definitely meets the challenge!!', '2003-02-24 20:57:42.000000', NULL, 1),
