(225368, 13013, 6451, '<td valign="top">Very nice image. It''s very clear for being underwater.  Nice idea as well.</td>', 'Very nice image. It''s very clear for being underwater.  Nice idea as well.', '2003-02-27 14:02:02.000000', NULL, 1),
(225371, 13027, 6451, '<td valign="top">Good image.  Nice use of shadows and display of the concept. Nice job.</td>', 'Good image.  Nice use of shadows and display of the concept. Nice job.', '2003-02-27 14:02:45.000000', NULL, 1),
(225373, 13083, 6451, '<td valign="top">Nice clear picture.  I like the use of the black and white scheme.  It is very well planned out and displays the concept well. Good job.</td>', 'Nice clear picture.  I like the use of the black and white scheme.  It is very well planned out and displays the concept well. Good job.', '2003-02-27 14:04:20.000000', NULL, 1),
(225375, 13048, 6451, '<td valign="top">Very strong image.  Nice use of the concept.  Also the hands are used well to communicate the feeling of the person in the image.  Great job.</td>', 'Very strong image.  Nice use of the concept.  Also the hands are used well to communicate the feeling of the person in the image.  Great job.', '2003-02-27 14:05:27.000000', NULL, 1),
