(225681, 12933, 6100, '<td valign="top">Quite effective in your framing and subject placement. Says, "despair" to me! Very good!</td>', 'Quite effective in your framing and subject placement. Says, "despair" to me! Very good!', '2003-02-27 21:18:56.000000', NULL, 1),
(225682, 12996, 6100, '<td valign="top">Although it seems a little grainy, that adds to the atmosphere and to the feeling of despair which you''ve captured quite nicely.</td>', 'Although it seems a little grainy, that adds to the atmosphere and to the feeling of despair which you''ve captured quite nicely.', '2003-02-27 21:19:44.000000', NULL, 1),
