(226204, 12956, 5822, '<td valign="top">Sorry, but I don''t associate cookies and kids with depair. But it''s a  cute picture nonetheless.</td>', 'Sorry, but I don''t associate cookies and kids with depair. But it''s a  cute picture nonetheless.', '2003-02-28 22:45:33.000000', NULL, 1),
(226205, 13034, 6325, '<td valign="top">Putting the subject in the distance and appearing insignificant (size-wise) works very well. The tone on tome except the subject is another good touch. I''m getting more depressed as I look at the picture - I guess it works.</td>', 'Putting the subject in the distance and appearing insignificant (size-wise) works very well. The tone on tome except the subject is another good touch. I''m getting more depressed as I look at the picture - I guess it works.', '2003-02-28 22:46:26.000000', NULL, 1),
(226206, 13072, 6325, '<td valign="top">This is one of the few landscapes that captures the challenge. Good composition and tonal depth.</td>', 'This is one of the few landscapes that captures the challenge. Good composition and tonal depth.', '2003-02-28 22:50:19.000000', NULL, 1),
(226207, 12966, 6325, '<td valign="top">Oops. Sorry I couldn''t see the shot.</td>', 'Oops. Sorry I couldn''t see the shot.', '2003-02-28 22:52:21.000000', NULL, 1),
