(226209, 13040, 5822, '<td valign="top">Wow! Grat impact...I love this shot.</td>', 'Wow! Grat impact...I love this shot.', '2003-02-28 22:59:29.000000', NULL, 1),
(226210, 12902, 6325, '<td valign="top">The concept is outstanding. I almost went right by it, but then it hit me. Something with more stopping power in the foreground and a contrived arrangement would have made this a really good image.</td>', 'The concept is outstanding. I almost went right by it, but then it hit me. Something with more stopping power in the foreground and a contrived arrangement would have made this a really good image.', '2003-02-28 23:00:58.000000', NULL, 1),
