(226212, 12871, 6325, '<td valign="top">Oh, this face is despair. Poor Ty. The background and composition really pull it down.</td>', 'Oh, this face is despair. Poor Ty. The background and composition really pull it down.', '2003-02-28 23:02:32.000000', NULL, 1),
(226213, 12793, 5822, '<td valign="top">Wish there was better tonal seperation between the woman''s head, hair and pants. In addition, the lock of hair on her arm was distracting and I initially thought it was a tatoo.</td>', 'Wish there was better tonal seperation between the woman''s head, hair and pants. In addition, the lock of hair on her arm was distracting and I initially thought it was a tatoo.', '2003-02-28 23:16:55.000000', NULL, 1),
(226214, 13073, 6325, '<td valign="top">Why put a bright flower in a despair shot? The eye goes to that. The shot is crooked, poorly composed, and not exposed well. You might have concentrated on the run-down buikding and left the flowers out. This would have allowed you to focus the building and expose it properly. Hope I''m not too harsh.</td>', 'Why put a bright flower in a despair shot? The eye goes to that. The shot is crooked, poorly composed, and not exposed well. You might have concentrated on the run-down buikding and left the flowers out. This would have allowed you to focus the building and expose it properly. Hope I''m not too harsh.', '2003-02-28 23:22:28.000000', NULL, 1),
(226215, 12775, 6325, '<td valign="top">Good composition and exposure.</td>', 'Good composition and exposure.', '2003-02-28 23:23:24.000000', NULL, 1),
(226216, 13118, 6325, '<td valign="top">Could have been good with a different approach to lighting. Darker and low angle light to bring out highlights. Shoot off angle.</td>', 'Could have been good with a different approach to lighting. Darker and low angle light to bring out highlights. Shoot off angle.', '2003-02-28 23:27:47.000000', NULL, 1),
