(226924, 13104, 3080, '<td valign="top">Excelent!  I as this was loading, I said "I hope he''s not wearing any shoes.  Then boom!  No shoes.  Great job.  Very nice dramatic lighting and the angle and framing/cropping is excelent.  Great despair shot. I would not change a thing.  Simply beautiful.  Good luck in the challenge. 10.</td>', 'Excelent!  I as this was loading, I said "I hope he''s not wearing any shoes.  Then boom!  No shoes.  Great job.  Very nice dramatic lighting and the angle and framing/cropping is excelent.  Great despair shot. I would not change a thing.  Simply beautiful.  Good luck in the challenge. 10.', '2003-03-02 22:18:47.000000', NULL, 1),
(226932, 12950, 3080, '<td valign="top">Definately gives off the feeling of despair.  I really think that the lighting is good. focus and clarity are also good.  The fact that this is on stairs sets this apart from some other similar shots, which is a good thing, but in a way, my eyes want to travel down the stairs which leads away from the subject.  not a huge problem at all, just an observation. nice shot. good luck in the challenge.</td>', 'Definately gives off the feeling of despair.  I really think that the lighting is good. focus and clarity are also good.  The fact that this is on stairs sets this apart from some other similar shots, which is a good thing, but in a way, my eyes want to travel down the stairs which leads away from the subject.  not a huge problem at all, just an observation. nice shot. good luck in the challenge.', '2003-03-02 22:42:58.000000', NULL, 1),
(226933, 13063, 3080, '<td valign="top">he actually looks like he''s smiling.  hehe.  looks like lunch to me!  color is good, focus and clarity are ok.  maybe just a tad soft, not serious thought.  I would like to see the whole pig in the shot.  you cut off his feet.  crop is just a tiny bit too tight.  I realize this may have been due to outside objects in the way though.  a nice shot.  good luck in the challenge.</td>', 'he actually looks like he''s smiling.  hehe.  looks like lunch to me!  color is good, focus and clarity are ok.  maybe just a tad soft, not serious thought.  I would like to see the whole pig in the shot.  you cut off his feet.  crop is just a tiny bit too tight.  I realize this may have been due to outside objects in the way though.  a nice shot.  good luck in the challenge.', '2003-03-02 22:45:55.000000', NULL, 1),
(226934, 13064, 3080, '<td valign="top">oh the poor guy!!  at first I didn''t see what it was, and then saw, it''s his swingset!  this is definately despair.  even I feel for the poor kid. lol.  as for the photo, only a few suggestions.  the lighting on the side of his face is just a bit harsh, and the focus seems also a bit soft.  neither of which has devestating effects on the photo, just some ovservations.  good luck in the challenge.</td>', 'oh the poor guy!!  at first I didn''t see what it was, and then saw, it''s his swingset!  this is definately despair.  even I feel for the poor kid. lol.  as for the photo, only a few suggestions.  the lighting on the side of his face is just a bit harsh, and the focus seems also a bit soft.  neither of which has devestating effects on the photo, just some ovservations.  good luck in the challenge.', '2003-03-02 22:49:37.000000', NULL, 1),
(226937, 12884, 3080, '<td valign="top">this must have been a long time ago! wow.  nice find.  it is sad that no one knew who it was.  definately a reflection of despair for someone thoguh.  focus and clarity are good  lighting conditions are also good.  angle and framing/cropping are ok.  I wonder how this would have looked from a lower angle, or did the weeds cover up the writing?  good luck in the challenge.</td>', 'this must have been a long time ago! wow.  nice find.  it is sad that no one knew who it was.  definately a reflection of despair for someone thoguh.  focus and clarity are good  lighting conditions are also good.  angle and framing/cropping are ok.  I wonder how this would have looked from a lower angle, or did the weeds cover up the writing?  good luck in the challenge.', '2003-03-02 22:51:59.000000', NULL, 1),
(226938, 12965, 1280, '<td valign="top">awwwwwwwww looks soooooo sad. Poor baby!</td>', 'awwwwwwwww looks soooooo sad. Poor baby!', '2003-03-02 22:51:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(226941, 12916, 3080, '<td valign="top">the darkness work here.  nicely.  but the blaring light around the candle is somewhat distracting from the subject.  I think that the focus is a bit soft, but In this situation, I think it works.  because we are seeing this "from the eyes of the subject" the blurryness adds to the fact that this person may have taken just a few too many of those pills and is losing clear sight of everything.  maybe it''s just me thought. hehe.  nice angle and framing/cropping. good luck in the challenge.</td>', 'the darkness work here.  nicely.  but the blaring light around the candle is somewhat distracting from the subject.  I think that the focus is a bit soft, but In this situation, I think it works.  because we are seeing this "from the eyes of the subject" the blurryness adds to the fact that this person may have taken just a few too many of those pills and is losing clear sight of everything.  maybe it''s just me thought. hehe.  nice angle and framing/cropping. good luck in the challenge.', '2003-03-02 22:54:44.000000', NULL, 1),
(226942, 12851, 1280, '<td valign="top">Nice and colorful!  I see your point of despair but isn''t real strong in that respect, imo.</td>', 'Nice and colorful!  I see your point of despair but isn''t real strong in that respect, imo.', '2003-03-02 22:55:05.000000', NULL, 1),
(226943, 12779, 4805, '<td valign="top">Might need a bit more depth of field to make a strong impact with this shot...it took a second look to realise that it was a dog in the background.</td>', 'Might need a bit more depth of field to make a strong impact with this shot...it took a second look to realise that it was a dog in the background.', '2003-03-02 22:56:27.000000', NULL, 1),
(226946, 12890, 4805, '<td valign="top">Hmm...red border overwhelms the shot. Would be much better with a neutral or greyscaled one.</td>', 'Hmm...red border overwhelms the shot. Would be much better with a neutral or greyscaled one.', '2003-03-02 22:57:29.000000', NULL, 1),
(226947, 13008, 1280, '<td valign="top">Good, simple depiction!  Strong statement.</td>', 'Good, simple depiction!  Strong statement.', '2003-03-02 22:57:33.000000', NULL, 1),
(226951, 12865, 4805, '<td valign="top">Nice clean image...Canon? Really like the composition.</td>', 'Nice clean image...Canon? Really like the composition.', '2003-03-02 22:59:41.000000', NULL, 1),
(226952, 13046, 1280, '<td valign="top">Tears do it!  I''m not sold on the very tight crop, but it''s ok.  The b&amp;W works well with this. The expression is good too.</td>', 'Tears do it!  I''m not sold on the very tight crop, but it''s ok.  The b&W works well with this. The expression is good too.', '2003-03-02 23:00:29.000000', NULL, 1),
(226954, 13073, 3080, '<td valign="top">this is a wonderful idea.  I think I''d like to see the house straightened up within the frame though.  it''s leaning a bit to the left.  looks like this was taken in poor lighting with flash.  was this done on purpose, or just ran out of time.  I wonder how this would have done in full light?  focus seems ok.  otherwise a nice shot.  I really like the idea behind it.  pretty flowers, old run down house.  nice find. good luck in the challenge.</td>', 'this is a wonderful idea.  I think I''d like to see the house straightened up within the frame though.  it''s leaning a bit to the left.  looks like this was taken in poor lighting with flash.  was this done on purpose, or just ran out of time.  I wonder how this would have done in full light?  focus seems ok.  otherwise a nice shot.  I really like the idea behind it.  pretty flowers, old run down house.  nice find. good luck in the challenge.', '2003-03-02 23:01:35.000000', NULL, 1),
(226955, 13027, 4805, '<td valign="top">Damn, no quarters for the wash...</td>', 'Damn, no quarters for the wash...', '2003-03-02 23:01:38.000000', NULL, 1),
(226957, 12817, 3080, '<td valign="top">great angle.  i like the "from the top" view.  lighting is good.  darker onthe subject, with some lighton the books so we can see whats going on.  focus and clarity are excelent.  great shot.  good luck in the challenge.</td>', 'great angle.  i like the "from the top" view.  lighting is good.  darker onthe subject, with some lighton the books so we can see whats going on.  focus and clarity are excelent.  great shot.  good luck in the challenge.', '2003-03-02 23:03:06.000000', NULL, 1),
(226958, 12856, 1280, '<td valign="top">Very funny!  Quite unexpected in this challenge.  The element of surprise works well. The problem I see is the glare between the mouth and eye.  I still like this though.  Very imaginative!!!</td>', 'Very funny!  Quite unexpected in this challenge.  The element of surprise works well. The problem I see is the glare between the mouth and eye.  I still like this though.  Very imaginative!!!', '2003-03-02 23:04:03.000000', NULL, 1),
(226959, 13029, 6008, '<td valign="top">The grainy effect makes it look really gritty and urban. The tone also matches it perfectly. My choice for number one!</td>', 'The grainy effect makes it look really gritty and urban. The tone also matches it perfectly. My choice for number one!', '2003-03-02 23:05:00.000000', NULL, 1),
(226961, 12933, 6349, '<td valign="top">Great photo.  I''ll be surprised if this doesn''t take first.  10</td>', 'Great photo.  I''ll be surprised if this doesn''t take first.  10', '2003-03-02 23:06:33.000000', NULL, 1),
(226962, 12874, 6349, '<td valign="top">Great shot.  Love the composition and choice of the red tone with the border.  The square tip of the shoe and that of the boat go very well together.  The most interesting shot this challenge.  Very artistic.  I would have called it view to a suicide myself.  10</td>', 'Great shot.  Love the composition and choice of the red tone with the border.  The square tip of the shoe and that of the boat go very well together.  The most interesting shot this challenge.  Very artistic.  I would have called it view to a suicide myself.  10', '2003-03-02 23:07:52.000000', NULL, 1),
(226963, 12881, 3080, '<td valign="top">definately despair.  sorry i dont even know what to say.  my son has about a million of these little cars, and this hits too close to home.  counting my blessings, and feeling lucky right now.  about the photo, I''m left wondering how old the person is in the shot.  nothing to say adult or child, but definatly makes me think child.  good focus and clarity.  good find for the challenge. (although not really a good find at all. you know what I mean) good luck in the challenge.</td>', 'definately despair.  sorry i dont even know what to say.  my son has about a million of these little cars, and this hits too close to home.  counting my blessings, and feeling lucky right now.  about the photo, I''m left wondering how old the person is in the shot.  nothing to say adult or child, but definatly makes me think child.  good focus and clarity.  good find for the challenge. (although not really a good find at all. you know what I mean) good luck in the challenge.', '2003-03-02 23:08:05.000000', NULL, 1),
(226964, 12805, 6008, '<td valign="top">Nice moody clouds, and the twigs/branches add to the composition. The border really adds to the image.</td>', 'Nice moody clouds, and the twigs/branches add to the composition. The border really adds to the image.', '2003-03-02 23:08:08.000000', NULL, 1),
(226965, 12977, 6349, '<td valign="top">Very nice photo.  Great lighting.  Best of it''s kind.  Good setup and composition.  Real?  Wish the hand didn''t have motion blur.  9</td>', 'Very nice photo.  Great lighting.  Best of it''s kind.  Good setup and composition.  Real?  Wish the hand didn''t have motion blur.  9', '2003-03-02 23:08:54.000000', NULL, 1),
(226966, 12886, 6349, '<td valign="top">Very despairing.  Sad, but an excellent photojournalistic photo.  9</td>', 'Very despairing.  Sad, but an excellent photojournalistic photo.  9', '2003-03-02 23:09:38.000000', NULL, 1),
(226967, 13083, 4805, '<td valign="top">Great expression! Like this one.</td>', 'Great expression! Like this one.', '2003-03-02 23:09:46.000000', NULL, 1),
(226968, 13039, 6008, '<td valign="top">I like the perspective/reflection - it really gives a good depth to the image and adds to the impact of it.</td>', 'I like the perspective/reflection - it really gives a good depth to the image and adds to the impact of it.', '2003-03-02 23:10:43.000000', NULL, 1),
(226970, 13042, 4805, '<td valign="top">One of the better posed suicide shots this week...strange to be able to write that. Like the depth of focus and the cool colour temperature.</td>', 'One of the better posed suicide shots this week...strange to be able to write that. Like the depth of focus and the cool colour temperature.', '2003-03-02 23:11:30.000000', NULL, 1),
(226971, 12814, 6349, '<td valign="top">Very nice shot.  Not really dispair, but I won''t mark you down for it.  Great colors, are they natural? 8</td>', 'Very nice shot.  Not really dispair, but I won''t mark you down for it.  Great colors, are they natural? 8', '2003-03-02 23:11:36.000000', NULL, 1),
(226972, 13053, 554, '<td valign="top">well done....my favorite</td>', 'well done....my favorite', '2003-03-02 23:11:38.000000', NULL, 1),
(226976, 12891, 6349, '<td valign="top">Excellent shot.  Great colors and composition. 8</td>', 'Excellent shot.  Great colors and composition. 8', '2003-03-02 23:12:27.000000', NULL, 1),
(226977, 13072, 6008, '<td valign="top">Good composition and great atmosphere.</td>', 'Good composition and great atmosphere.', '2003-03-02 23:12:36.000000', NULL, 1),
(226978, 12992, 6349, '<td valign="top">Wow.  great photojournalism.  I would have liked to see it a bit larger. 8</td>', 'Wow.  great photojournalism.  I would have liked to see it a bit larger. 8', '2003-03-02 23:13:07.000000', NULL, 1),
(226979, 12805, 1280, '<td valign="top">Increase the contrast on this and it would really pop.  I can feel the despair here.</td>', 'Increase the contrast on this and it would really pop.  I can feel the despair here.', '2003-03-02 23:13:43.000000', NULL, 1),
(226980, 12857, 6349, '<td valign="top">Quite possible the most disturbing photo this challenge, even more so than the actual self mutilation/ suicide shots.  That''s a good thing.  8</td>', 'Quite possible the most disturbing photo this challenge, even more so than the actual self mutilation/ suicide shots.  That''s a good thing.  8', '2003-03-02 23:13:55.000000', NULL, 1),
(226983, 13040, 6349, '<td valign="top">Very interesting editing technique.  Very artistic.  The sunburst is a little strange inverted and doesn''t quite work for me.  8</td>', 'Very interesting editing technique.  Very artistic.  The sunburst is a little strange inverted and doesn''t quite work for me.  8', '2003-03-02 23:15:23.000000', NULL, 1),
(226984, 12901, 6349, '<td valign="top">I don''t usually like the chess shots, but the lighting, composition, and set up are really good on this one.  Light verses darkness, good verses evil.  Nice job.  8</td>', 'I don''t usually like the chess shots, but the lighting, composition, and set up are really good on this one.  Light verses darkness, good verses evil.  Nice job.  8', '2003-03-02 23:16:20.000000', NULL, 1),
(226985, 13028, 6349, '<td valign="top">Excellent shot.  Great subject and composition.  I would have liked it with more colors or in black and white.  8</td>', 'Excellent shot.  Great subject and composition.  I would have liked it with more colors or in black and white.  8', '2003-03-02 23:16:59.000000', NULL, 1),
(226986, 12886, 4430, '<td valign="top">The most moving photo of the challenge, well done.  To look at this child''s eyes is heartbreaking.</td>', 'The most moving photo of the challenge, well done.  To look at this child''s eyes is heartbreaking.', '2003-03-02 23:17:17.000000', NULL, 1),
(226988, 12906, 6349, '<td valign="top">Great shot, I really like it.  Simple yet elagant in a spooky way.  Good lines and texture. 8</td>', 'Great shot, I really like it.  Simple yet elagant in a spooky way.  Good lines and texture. 8', '2003-03-02 23:18:22.000000', NULL, 1),
(226990, 12959, 6349, '<td valign="top">Nice shot.  I''ve been there.  I like the slight blurryness and almost magical feeling to the light and smoke.  8</td>', 'Nice shot.  I''ve been there.  I like the slight blurryness and almost magical feeling to the light and smoke.  8', '2003-03-02 23:19:09.000000', NULL, 1),
(226991, 12873, 6349, '<td valign="top">really nice photograph.  Well, not nice, but good.  good color choice with the blue, it gives the headstones a cold unnatural feeling.  8</td>', 'really nice photograph.  Well, not nice, but good.  good color choice with the blue, it gives the headstones a cold unnatural feeling.  8', '2003-03-02 23:20:11.000000', NULL, 1),
(226992, 12790, 616, '<td valign="top">Nice, very nice. Your subjects are great! The only thing that I wood have prefered was that there was a bit more saturation in the shot. Unfortunately this was probably out of your hands because there appears to be an over cast on that day. nicely done</td>', 'Nice, very nice. Your subjects are great! The only thing that I wood have prefered was that there was a bit more saturation in the shot. Unfortunately this was probably out of your hands because there appears to be an over cast on that day. nicely done', '2003-03-02 23:20:24.000000', NULL, 1),
(226993, 12775, 6349, '<td valign="top">Very nice photograph.  Classical.  Good choice for B+W.  8</td>', 'Very nice photograph.  Classical.  Good choice for B+W.  8', '2003-03-02 23:20:49.000000', NULL, 1),
(226994, 13083, 6349, '<td valign="top">I like George.  I like the sign.  I like the composition.  It doesn''t seem forced.  A larger aperature might have been interesting.  8</td>', 'I like George.  I like the sign.  I like the composition.  It doesn''t seem forced.  A larger aperature might have been interesting.  8', '2003-03-02 23:22:11.000000', NULL, 1),
(226995, 12996, 6349, '<td valign="top">I almost submitted a similar photo.  Nice job.  I like that the shadow is on this side of the hand.  I would have liked to see it in color as well.  7</td>', 'I almost submitted a similar photo.  Nice job.  I like that the shadow is on this side of the hand.  I would have liked to see it in color as well.  7', '2003-03-02 23:23:05.000000', NULL, 1),
(226996, 12903, 6349, '<td valign="top">lol.  I love the error.  Very interesting shot and interesting take on the challenge subject.  Good photo.  Good expression. 7</td>', 'lol.  I love the error.  Very interesting shot and interesting take on the challenge subject.  Good photo.  Good expression. 7', '2003-03-02 23:23:52.000000', NULL, 1),
(226997, 13050, 6349, '<td valign="top">Nice picture.  I like it.  Not really that despairing though, more cute, still, a 7 from me.</td>', 'Nice picture.  I like it.  Not really that despairing though, more cute, still, a 7 from me.', '2003-03-02 23:24:46.000000', NULL, 1),
(226998, 13094, 6349, '<td valign="top">Wow.  Great lighting.  Great composition/perspective.  7</td>', 'Wow.  Great lighting.  Great composition/perspective.  7', '2003-03-02 23:25:24.000000', NULL, 1),
(226999, 12921, 1280, '<td valign="top">Sad, such a young life.</td>', 'Sad, such a young life.', '2003-03-02 23:25:47.000000', NULL, 1),
(227000, 12989, 6349, '<td valign="top">very provocative lines and texture.  I like it a lot.  7</td>', 'very provocative lines and texture.  I like it a lot.  7', '2003-03-02 23:26:06.000000', NULL, 1),
(227001, 12986, 6349, '<td valign="top">Great shot.  I love taking animal shots myself.  I''m sure you saw my cheetah in the yellow challenge.  I had a similar photo of an elephant from that day but it was through bars.  Love it.  9</td>', 'Great shot.  I love taking animal shots myself.  I''m sure you saw my cheetah in the yellow challenge.  I had a similar photo of an elephant from that day but it was through bars.  Love it.  9', '2003-03-02 23:27:19.000000', NULL, 1),
(227003, 12782, 6349, '<td valign="top">I really like this shot.  It looks like an illustration out of a fantasy book.  Awesome.  I don\''t find much despair in it so I was going to give you a 7, but I think I\''ll still give you an 8.  Love the saturation of green.</td>', 'I really like this shot.  It looks like an illustration out of a fantasy book.  Awesome.  I don\''t find much despair in it so I was going to give you a 7, but I think I\''ll still give you an 8.  Love the saturation of green.', '2003-03-02 23:27:37.000000', NULL, 1),
(227005, 13039, 6349, '<td valign="top">Great shot.  Good perspective.  It seems a bit overexposed and the aperature may be a bit small.  7</td>', 'Great shot.  Good perspective.  It seems a bit overexposed and the aperature may be a bit small.  7', '2003-03-02 23:29:07.000000', NULL, 1),
(227006, 13116, 6349, '<td valign="top">good lighting.  i think it would look good in black and white with only the red of the blood on the blade. 7</td>', 'good lighting.  i think it would look good in black and white with only the red of the blood on the blade. 7', '2003-03-02 23:29:58.000000', NULL, 1),
(227007, 12829, 6349, '<td valign="top">Great photo.  Interesting shot for the challenge.  It definetely implies a sense of despair to me.  8</td>', 'Great photo.  Interesting shot for the challenge.  It definetely implies a sense of despair to me.  8', '2003-03-02 23:30:54.000000', NULL, 1),
(227008, 12851, 6349, '<td valign="top">I like.  Great use of the motion blur.  Lovely colors and sky.  Very crisp.  7</td>', 'I like.  Great use of the motion blur.  Lovely colors and sky.  Very crisp.  7', '2003-03-02 23:31:51.000000', NULL, 1),
(227009, 13106, 1280, '<td valign="top">I think that perhaps you misunderstood the challenge?  But I may be misunderstanding your picture.  If I am, I''m sorry.</td>', 'I think that perhaps you misunderstood the challenge?  But I may be misunderstanding your picture.  If I am, I''m sorry.', '2003-03-02 23:32:15.000000', NULL, 1),
(227010, 13076, 6349, '<td valign="top">I like it.  It seems a bit blurry, but perhaps that''s the camo background messing with my eyes.  6</td>', 'I like it.  It seems a bit blurry, but perhaps that''s the camo background messing with my eyes.  6', '2003-03-02 23:32:29.000000', NULL, 1),
(227011, 12828, 6349, '<td valign="top">yes, it does.  i need to go get more now.  thanks a lot.  7</td>', 'yes, it does.  i need to go get more now.  thanks a lot.  7', '2003-03-02 23:33:21.000000', NULL, 1),
(227012, 12994, 1280, '<td valign="top">Ohhh geee...I''m trying to understand, but I don''t get it.  I love the colors though. Good luck!  :-)</td>', 'Ohhh geee...I''m trying to understand, but I don''t get it.  I love the colors though. Good luck!  :-)', '2003-03-02 23:33:51.000000', NULL, 1),
(227013, 12966, 6349, '<td valign="top">sorry about whatever happened with your upload.  better luck next time!</td>', 'sorry about whatever happened with your upload.  better luck next time!', '2003-03-02 23:34:45.000000', NULL, 1),
(227014, 12912, 6349, '<td valign="top">Very emotive shot.  i''m not sure you meant it in the way that i took it recognizing the statue as a crying buddha.  Great composition and tone.  The red light seems more angry than despairing to me as well, but it also suggests the fires of hell which is good.  I would have liked to see such a powerful image in slightly more powerful spotlighting, especially to get rid of the border crease.  It would have been really awesome to shine the only light through the cross, especially since you already had the red valentine''s wrap out!<br/><br/><i>Message edited by author 2003-03-04 03:35:59.</i></td>', 'Very emotive shot.  i''m not sure you meant it in the way that i took it recognizing the statue as a crying buddha.  Great composition and tone.  The red light seems more angry than despairing to me as well, but it also suggests the fires of hell which is good.  I would have liked to see such a powerful image in slightly more powerful spotlighting, especially to get rid of the border crease.  It would have been really awesome to shine the only light through the cross, especially since you already had the red valentine''s wrap out!', '2003-03-02 23:36:32.000000', '2003-03-04 03:35:59.000000', 1),
(227015, 12778, 6349, '<td valign="top">ok. there''s no way that is real!  I would have liked a better composed picture of it if it is!</td>', 'ok. there''s no way that is real!  I would have liked a better composed picture of it if it is!', '2003-03-02 23:38:12.000000', NULL, 1),
(227018, 12946, 1280, '<td valign="top">Good composition.  The concept is very good too, and well executed.</td>', 'Good composition.  The concept is very good too, and well executed.', '2003-03-02 23:42:39.000000', NULL, 1),
(227023, 12936, 1280, '<td valign="top">Yes....it saddens me to see houses deteriorate to the point that no one can use them.  What a waste!</td>', 'Yes....it saddens me to see houses deteriorate to the point that no one can use them.  What a waste!', '2003-03-02 23:44:40.000000', NULL, 1),
(227027, 12770, 5044, '<td valign="top">Took me a while to figure out what this was. Ouch! Better start shoveling now. Very well lit and framed.</td>', 'Took me a while to figure out what this was. Ouch! Better start shoveling now. Very well lit and framed.', '2003-03-02 23:47:49.000000', NULL, 1),
(227028, 12873, 1280, '<td valign="top">Strong graphical image.   I don''t necessarily see the despair, since death is a natural part of life, just part of the cycle.   I mean I know death has the sting of separation from loved ones,  but I think your real strength here is the lines, and pattern of the headstones. Good!</td>', 'Strong graphical image.   I don''t necessarily see the despair, since death is a natural part of life, just part of the cycle.   I mean I know death has the sting of separation from loved ones,  but I think your real strength here is the lines, and pattern of the headstones. Good!', '2003-03-02 23:48:01.000000', NULL, 1),
(227029, 12814, 244, '<td valign="top">great shot, how did you get the reds to show up so well?  7 Corey<br/><br/><br/><i>Message edited by author 2003-03-07 00:20:05.</i></td>', 'great shot, how did you get the reds to show up so well?  7 Corey', '2003-03-02 23:49:16.000000', '2003-03-07 00:20:05.000000', 1),
(227032, 13013, 3018, '<td valign="top">Hell looks horrible.  I wonder why won''t you try to escape again.</td>', 'Hell looks horrible.  I wonder why won''t you try to escape again.', '2003-03-02 23:51:35.000000', NULL, 1),
(227033, 13016, 1280, '<td valign="top"></td>', '', '2003-03-02 23:53:59.000000', NULL, 1),
(227034, 12930, 4267, '<td valign="top">seems like too much digital art rather than photography</td>', 'seems like too much digital art rather than photography', '2003-03-02 23:55:01.000000', NULL, 1),
